        $this->sot['started_at'] = $v;
        $this->assertEquals($v, $this->sot['started_at']);
        $this->assertTrue(isset($this->sot['started_at']));
        $this->sot['started_at'] = null;
        $this->assertFalse(isset($this->sot['started_at']));
    }

